   160	        HttpHeaders headers = new HttpHeaders();
   161	        Pet pet = petMapper.toPet(petFieldsDto);
   162	        owner.setId(ownerId);
   163	        pet.setOwner(owner);
   164	        pet.getType().setName(null);
