    16	/**
    17	 * Maps Owner & OwnerDto using Mapstruct
    18	 */
    19	@Mapper(uses = PetMapper.class)
    20	public interface OwnerMapper {
    21	
    22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    23	    @Mapping(target = "initials", expression = "java((owner.getFirstName().charAt(0) + \".\" + owner.getLastName().charAt(0) + \".\").toUpperCase())")
    24	    @Mapping(target = "householdId", expression = "java(org.springframework.samples.petclinic.service.HouseholdMatcher.householdId(owner))")
    25	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
    26	    @Mapping(target = "membershipTier", expression = "java(Integer.valueOf(0).equals(owner.getNamesakeCount()) && owner.getEmail() != null && !owner.getEmail().isBlank() ? \"SILVER\" : \"BRONZE\")")
    27	    OwnerDto toOwnerDto(Owner owner);
    28	
    29	    Owner toOwner(OwnerDto ownerDto);
    30	
    31	    @Mapping(target = "id", ignore = true)
    32	    @Mapping(target = "pets", ignore = true)
    33	    @Mapping(target = "telephone", qualifiedByName = "normalizeTelephone")
    34	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.service.AddressNormalizer.normalize(ownerDto.getAddress()))")
    35	    Owner toOwner(OwnerFieldsDto ownerDto);
    36	
    37	    /**
    38	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
    39	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
    40	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
    41	     * the '+', else the number is rejected as invalid.
