    43	    @Named("normalizeTelephone")
    44	    default String normalizeTelephone(String telephone) {
    45	        if (telephone == null) {
    46	            return null;
    47	        }
    48	        boolean international = telephone.trim().startsWith("+");
    49	        String digits = telephone.replaceAll("\\D", "");
    50	        if (!international) {
    51	            if (digits.startsWith("0")) {
    52	                digits = digits.substring(1);
    53	            }
    54	            digits = "61" + digits;
    55	        }
    56	        if (digits.length() < 8 || digits.length() > 15) {
    57	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
    58	        }
    59	        return "+" + digits;
    60	    }
